    public static int tRefuse(int emonT, int drop, int at, int val, String msg) {
        // The page's flat form, with `drop` cells cut off its end and cell `at` (when not -1) set to `val`, is refused and writes nothing.
        emon.Port.Cells v = emon.Port.newCells();
        emon.Port.Cells got = emon.Port.newCells();
        tFlat(v);
        if (drop > 0) {
            emon.Port.cellsDrop(v, drop);
        }
        if (at >= 0) {
            emon.Port.cellsSet(v, at, val);
        }
        emon.Testport.assertEq(Ocrport.oxFlat(v, 9, got), -1, msg);
        emon.Testport.assertEq(emon.Port.cellsLen(got), 0, msg);
        return 0;
    }
